/**
 * 学习台账（study log）
 *
 * 书架第一层「01 当前学习」和第四层「04 学习档案」只认真实发生过的事：哪本书
 * 被打开过、在书里点开了哪个章节、在钢琴上练过哪个分区、哪本书被标记成已完成。
 * 这些事发生在用户手上、记在本机，登录与否都能用 —— 和书架「不做推荐、不自动
 * 生成」的原则一致：书架上出现的每一本书都能追到用户自己的一个动作。
 *
 * 记的是「事件流」而不是「进度数字」：进度、最近章节、复习次数都是从事件里算
 * 出来的，将来换一种展示（卡片、周报）不必重写记录方式。
 *
 * 2026-10-14 起事件流上了云端同步（登录云端账号就自动走）：它是只增不减的
 * 一类，两边都有时按并集合（mergeStudyLogs），不比时间 —— 两台设备各学了
 * 一整天，合起来才是这一天的全貌。这份存档不按 Leafia 账号分桶（裸键），
 * 云端槽照原样收走。
 */
import { registerCloudSlot, touchCloudSlot } from "../../lib/cloudSync";

export const STUDY_LOG_STORAGE_KEY = "leafia:study-log:v1";

/** 事件上限。超出后丢最早的一条 —— 台账是「最近在学什么」，不是档案馆。 */
const MAX_EVENTS = 600;
/** 同一次学习里反复打开同一本书，算一次，只把时间往前推。 */
const OPEN_MERGE_MS = 30 * 60 * 1000;
/** 同一章节反复点开，同上。 */
const TOPIC_MERGE_MS = 30 * 60 * 1000;
/** 连续弹键算一次练习，键数累加。 */
const PRACTICE_MERGE_MS = 2 * 60 * 1000;

export type StudyEvent =
  | { kind: "open"; at: number; bookId: string }
  | { kind: "topic"; at: number; bookId: string; topic: string }
  | { kind: "practice"; at: number; region: number; keys: number }
  | { kind: "complete"; at: number; bookId: string }
  | { kind: "resume"; at: number; bookId: string }
  | {
      kind: "knowledge-review";
      at: number;
      bookId: string;
      nodeId: string;
      correct: boolean;
    }
  | {
      kind: "quiz-completed";
      at: number;
      bookId: string;
      moduleId?: string;
      correct: number;
      total: number;
    }
  | {
      kind: "word-review";
      at: number;
      reviewed: number;
      passed: number;
      failed: number;
    }
  | {
      kind: "card-created";
      at: number;
      cardId: string;
      categoryId: string;
    };

export interface BookStudyRecord {
  bookId: string;
  firstAt: number;
  /** 最近一次学习时间（打开、或点开章节）。 */
  lastAt: number;
  /** 最近点开的章节。 */
  lastTopic: string | null;
  /** 点开过的章节，去重。 */
  topics: string[];
  openCount: number;
  /** 已完成时间；标记完成后又继续学，就回到 null。 */
  completedAt: number | null;
}

export interface PracticeSummary {
  region: number;
  sessions: number;
  keys: number;
  lastAt: number;
}

/**
 * 同一本书可以同时站在两层书架上：03 语言花园里的原本，和 01 当前学习里平放
 * 的那本（书脊的副本，id 带 `#now` 后缀 —— 手柄和 React key 都必须唯一）。
 * 但「这本书」在用户眼里只有一本，所以对外的身份一律用 base id。
 */
export function bookBaseId(id: string): string {
  const [base] = String(id).split("#");
  return base || String(id);
}

function isStudyEvent(value: unknown): value is StudyEvent {
  if (!value || typeof value !== "object") return false;
  const event = value as {
    kind?: unknown;
    at?: unknown;
    bookId?: unknown;
    topic?: unknown;
    region?: unknown;
    keys?: unknown;
    nodeId?: unknown;
    correct?: unknown;
    moduleId?: unknown;
    total?: unknown;
    reviewed?: unknown;
    passed?: unknown;
    failed?: unknown;
    cardId?: unknown;
    categoryId?: unknown;
  };
  if (typeof event.at !== "number" || !Number.isFinite(event.at)) return false;
  switch (event.kind) {
    case "open":
    case "complete":
    case "resume":
      return typeof event.bookId === "string";
    case "topic":
      return typeof event.bookId === "string" && typeof event.topic === "string";
    case "knowledge-review":
      return (
        typeof event.bookId === "string" &&
        typeof event.nodeId === "string" &&
        typeof event.correct === "boolean"
      );
    case "quiz-completed":
      return (
        typeof event.bookId === "string" &&
        typeof event.correct === "number" &&
        typeof event.total === "number"
      );
    case "word-review":
      return (
        typeof event.reviewed === "number" &&
        typeof event.passed === "number" &&
        typeof event.failed === "number"
      );
    case "card-created":
      return (
        typeof event.cardId === "string" &&
        typeof event.categoryId === "string"
      );
    case "practice":
      return (
        typeof event.region === "number" &&
        Number.isFinite(event.region) &&
        typeof event.keys === "number"
      );
    default:
      return false;
  }
}

export function loadStudyLog(): StudyEvent[] {
  if (typeof localStorage === "undefined") return [];
  try {
    const parsed = JSON.parse(
      localStorage.getItem(STUDY_LOG_STORAGE_KEY) ?? "[]",
    );
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(isStudyEvent).slice(-MAX_EVENTS);
  } catch {
    return [];
  }
}

export function saveStudyLog(events: StudyEvent[]): void {
  if (typeof localStorage === "undefined") return;
  try {
    localStorage.setItem(
      STUDY_LOG_STORAGE_KEY,
      JSON.stringify(events.slice(-MAX_EVENTS)),
    );
  } catch {
    // 隐私模式 / 配额满：这次没记上而已，界面照常。
  }
  // 云端同步：本机写完，稍后推上去（没登录云端时它什么都不做）。
  touchCloudSlot("study-log");
}

export function recordStudyEvent(event: StudyEvent): StudyEvent[] {
  const next = appendStudyEvent(loadStudyLog(), event);
  saveStudyLog(next);
  return next;
}

function sameTarget(a: StudyEvent, b: StudyEvent): boolean {
  if (a.kind === "practice") {
    return b.kind === "practice" && a.region === b.region;
  }
  if (a.kind === "topic") {
    return b.kind === "topic" && a.bookId === b.bookId && a.topic === b.topic;
  }
  // 「打开」和「标记完成」是两件不同的事：刚打开就标记完成，不能让完成把
  // 打开吃掉 —— 合并只发生在同一种动作的重复之间。
  if (b.kind !== a.kind) return false;
  if (
    a.kind === "word-review" ||
    a.kind === "card-created" ||
    a.kind === "knowledge-review" ||
    a.kind === "quiz-completed"
  ) {
    return false;
  }
  return (
    "bookId" in a &&
    "bookId" in b &&
    a.bookId === b.bookId
  );
}

function mergeWindow(kind: StudyEvent["kind"]): number {
  if (kind === "practice") return PRACTICE_MERGE_MS;
  if (kind === "topic") return TOPIC_MERGE_MS;
  if (
    kind === "word-review" ||
    kind === "card-created" ||
    kind === "knowledge-review" ||
    kind === "quiz-completed"
  ) {
    return 0;
  }
  return OPEN_MERGE_MS;
}

/**
 * 追加一条事件；如果是同一件事的连续动作（同一本书刚开过、同一章节刚点过、
 * 同一个分区刚练过），就合并成上一次事件，而不是把台账灌成一串重复。
 */
export function appendStudyEvent(
  log: StudyEvent[],
  event: StudyEvent,
): StudyEvent[] {
  const next = [...log];
  const window = mergeWindow(event.kind);
  let mergeIndex = -1;
  for (let index = next.length - 1; index >= 0; index -= 1) {
    const candidate = next[index]!;
    if (sameTarget(candidate, event)) {
      if (event.at - candidate.at <= window) mergeIndex = index;
      break;
    }
  }

  if (mergeIndex >= 0) {
    const previous = next[mergeIndex]!;
    next[mergeIndex] =
      previous.kind === "practice" && event.kind === "practice"
        ? { ...event, keys: previous.keys + event.keys }
        : event;
  } else {
    next.push(event);
  }

  return next.slice(-MAX_EVENTS);
}

export function summarizeBooks(
  log: StudyEvent[],
): Map<string, BookStudyRecord> {
  const records = new Map<string, BookStudyRecord>();
  const completions = new Map<string, { complete: number; resume: number }>();
  // 事件流不是严格按时间排的（合并会把某条的时间往后挪），所以「最近章节」
  // 得单独比时间，不能靠遍历顺序。
  const topicTimes = new Map<string, number>();

  const touch = (bookId: string, at: number) => {
    const existing = records.get(bookId);
    if (existing) {
      existing.lastAt = Math.max(existing.lastAt, at);
      existing.firstAt = Math.min(existing.firstAt, at);
      return existing;
    }
    const created: BookStudyRecord = {
      bookId,
      firstAt: at,
      lastAt: at,
      lastTopic: null,
      topics: [],
      openCount: 0,
      completedAt: null,
    };
    records.set(bookId, created);
    return created;
  };

  for (const event of log) {
    if (event.kind === "open") {
      touch(event.bookId, event.at).openCount += 1;
      continue;
    }
    if (event.kind === "topic") {
      const record = touch(event.bookId, event.at);
      if (!record.topics.includes(event.topic)) record.topics.push(event.topic);
      if (event.at >= (topicTimes.get(event.bookId) ?? -Infinity)) {
        record.lastTopic = event.topic;
        topicTimes.set(event.bookId, event.at);
      }
      continue;
    }
    if (event.kind === "complete" || event.kind === "resume") {
      touch(event.bookId, event.at);
      const entry = completions.get(event.bookId) ?? {
        complete: 0,
        resume: 0,
      };
      if (event.kind === "complete") entry.complete = Math.max(entry.complete, event.at);
      else entry.resume = Math.max(entry.resume, event.at);
      completions.set(event.bookId, entry);
      continue;
    }
    if (event.kind === "knowledge-review" || event.kind === "quiz-completed") {
      touch(event.bookId, event.at);
    }
  }

  completions.forEach((entry, bookId) => {
    const record = records.get(bookId);
    if (!record) return;
    record.completedAt = entry.complete > entry.resume ? entry.complete : null;
  });

  return records;
}

/** 正在学习的书：有过动作、且没有被标记完成，按最近学习时间降序。 */
export function currentLearningBooks(
  log: StudyEvent[],
  limit = 3,
): BookStudyRecord[] {
  return [...summarizeBooks(log).values()]
    .filter(
      (record) =>
        record.completedAt === null &&
        (record.openCount > 0 || record.topics.length > 0),
    )
    .sort((a, b) => b.lastAt - a.lastAt)
    .slice(0, Math.max(0, limit));
}

export function completedBooks(log: StudyEvent[]): BookStudyRecord[] {
  return [...summarizeBooks(log).values()]
    .filter((record) => record.completedAt !== null)
    .sort((a, b) => (b.completedAt ?? 0) - (a.completedAt ?? 0));
}

export function practiceSummary(log: StudyEvent[]): PracticeSummary[] {
  const byRegion = new Map<number, PracticeSummary>();
  for (const event of log) {
    if (event.kind !== "practice") continue;
    const existing = byRegion.get(event.region);
    if (existing) {
      existing.sessions += 1;
      existing.keys += event.keys;
      existing.lastAt = Math.max(existing.lastAt, event.at);
    } else {
      byRegion.set(event.region, {
        region: event.region,
        sessions: 1,
        keys: event.keys,
        lastAt: event.at,
      });
    }
  }
  return [...byRegion.values()].sort((a, b) => b.lastAt - a.lastAt);
}

/** 「3 天前」「昨天 20:41」这类相对时间。台账是给人看的，不摆时间戳。 */
export function formatRelativeTime(at: number, now = Date.now()): string {
  const diff = now - at;
  if (!Number.isFinite(diff)) return "";
  if (diff < 60 * 1000) return "刚刚";
  if (diff < 60 * 60 * 1000) {
    return `${Math.max(1, Math.round(diff / 60000))} 分钟前`;
  }
  const day = 24 * 60 * 60 * 1000;
  const startOfToday = new Date(now).setHours(0, 0, 0, 0);
  const days = Math.floor((startOfToday - new Date(at).setHours(0, 0, 0, 0)) / day);
  const clock = new Date(at).toLocaleTimeString("zh-CN", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  });
  if (days <= 0) return `今天 ${clock}`;
  if (days === 1) return `昨天 ${clock}`;
  if (days < 7) return `${days} 天前`;
  return `${new Date(at).getMonth() + 1} 月 ${new Date(at).getDate()} 日`;
}

/* -------------------------------------------------------- 云端同步（学习台账） */

function studyEventsOf(value: unknown): StudyEvent[] {
  if (!Array.isArray(value)) return [];
  return value.filter((entry): entry is StudyEvent => {
    if (!entry || typeof entry !== "object") return false;
    const candidate = entry as Partial<StudyEvent>;
    return (
      typeof candidate.kind === "string" &&
      typeof candidate.at === "number" &&
      isStudyEvent(entry)
    );
  });
}

/**
 * 台账的并集：两条流水拼一起，同一件事（整条 JSON 一样）只留一条，按时间
 * 排好、留最近 MAX_EVENTS 条。两边合出来的顺序是确定的 —— 同一对输入永远
 * 得出同一份结果，两台设备合完再推不会来回打架。
 * 注意它不做「合并窗口」（appendStudyEvent 那种）——跨设备没法判断两条
 * 5 分钟内的「打开同一本书」是不是同一次，宁可多留一条流水。
 */
export function mergeStudyLogs(local: unknown, remote: unknown): StudyEvent[] {
  const seen = new Set<string>();
  const all: StudyEvent[] = [];
  for (const event of [...studyEventsOf(local), ...studyEventsOf(remote)]) {
    const key = JSON.stringify(event);
    if (seen.has(key)) continue;
    seen.add(key);
    all.push(event);
  }
  all.sort((a, b) => a.at - b.at);
  return all.slice(-MAX_EVENTS);
}

registerCloudSlot({
  key: "study-log",
  label: "学习台账",
  read() {
    const events = loadStudyLog();
    return events.length === 0 ? null : events;
  },
  apply(value) {
    const events = studyEventsOf(value);
    saveStudyLog(events);
  },
  merge: mergeStudyLogs,
});
